import React, { useEffect, useState, useCallback } from 'react';
import { Search, Download, RefreshCw, UserPlus, Shield, ShieldOff, Smartphone, Loader2, AlertCircle, X, Trash2, Users2 } from 'lucide-react';
import { getUsers, revokeLicense, activateLicense, resetDevices, createUser, deleteUsers } from '../services/api';
import { useToast } from '../components/ui/ToastProvider';

interface User {
  id: string;
  email: string;
  created_at: string;
  last_sign_in_at: string | null;
  full_name?: string;
  phone?: string;
  office_member_of?: { owner_id: string; owner_email: string } | null;
  is_office_owner?: boolean;
  license?: {
    id: string;
    license_type: string;
    is_active: boolean;
    expires_at: string | null;
    activated_at: string;
  } | null;
  device_count: number;
}

const LICENSE_LABELS: Record<string, string> = {
  trial: 'تجريبي', standard: 'قياسي', pro: 'احترافي', office: 'مكتبي', office_member: 'عضو مكتب'
};

const LICENSE_BADGE: Record<string, string> = {
  trial: 'badge-blue', standard: 'badge-green', pro: 'badge-purple', office: 'badge-orange', office_member: 'badge-gray'
};

function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debouncedValue;
}

// Create User Modal
function CreateUserModal({ onClose, onSuccess }: { onClose: () => void; onSuccess: () => void }) {
  const toast = useToast();
  const [email, setEmail] = useState('');
  const [licenseType, setLicenseType] = useState('standard');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const result = await createUser({ email, licenseType });
    if (result.success) {
      toast.success('تم إنشاء المستخدم بنجاح');
      onSuccess();
      onClose();
    } else {
      toast.error(result.error || 'فشل إنشاء المستخدم');
    }
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-dark-900 border border-dark-700 rounded-2xl w-full max-w-md shadow-2xl animate-fade-in">
        <div className="flex items-center justify-between p-6 border-b border-dark-800">
          <h3 className="text-lg font-bold text-dark-50">إضافة مستخدم جديد</h3>
          <button onClick={onClose} className="text-dark-400 hover:text-dark-200"><X className="w-5 h-5" /></button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-sm text-dark-300 mb-2">البريد الإلكتروني</label>
            <input type="email" value={email} onChange={e => setEmail(e.target.value)}
              required className="input-field" placeholder="user@example.com" dir="ltr" />
          </div>
          <div>
            <label className="block text-sm text-dark-300 mb-2">نوع الترخيص</label>
            <select value={licenseType} onChange={e => setLicenseType(e.target.value)} className="select-field">
              <option value="trial">تجريبي (30 يوم)</option>
              <option value="standard">قياسي</option>
              <option value="pro">احترافي</option>
              <option value="office">مكتبي</option>
            </select>
          </div>
          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose} className="btn-secondary flex-1 justify-center">إلغاء</button>
            <button type="submit" disabled={loading} className="btn-primary flex-1 justify-center">
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <UserPlus className="w-4 h-4" />}
              إنشاء
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export function Users() {
  const toast = useToast();
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [bulkLoading, setBulkLoading] = useState(false);

  function toggleSelect(id: string) {
    setSelected(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  function toggleSelectAll() {
    if (selected.size === users.length) setSelected(new Set());
    else setSelected(new Set(users.map(u => u.id)));
  }

  async function handleBulkDelete() {
    const n = selected.size;
    if (!confirm(`سيتم حذف ${n} مستخدم/مستخدمين نهائياً مع تراخيصهم وأجهزتهم وكل بياناتهم.\nهذا الإجراء لا يمكن التراجع عنه. متابعة؟`)) return;
    setBulkLoading(true);
    const result = await deleteUsers({ userIds: [...selected] });
    if (result.success) {
      const failed = ((result.data as any)?.results || []).filter((r: any) => !r.ok);
      toast.success(failed.length === 0
        ? `تم حذف ${n} مستخدم`
        : `حُذف بعض المستخدمين — تعذر حذف ${failed.length} (حسابات أدمن محمية)`);
      await loadUsers();
      setSelected(new Set());
    } else {
      toast.error(result.error || 'فشل الحذف');
    }
    setBulkLoading(false);
  }

  async function handleDeleteSingle(userId: string) {
    if (!confirm('حذف هذا المستخدم نهائياً مع ترخيصه وأجهزته وكل بياناته؟ لا يمكن التراجع.')) return;
    setActionLoading(userId + '_delete');
    const result = await deleteUsers({ userIds: [userId] });
    if (result.success) {
      toast.success('تم حذف المستخدم');
      await loadUsers();
    } else {
      toast.error(result.error || 'فشل الحذف');
    }
    setActionLoading(null);
  }

  const debouncedSearch = useDebounce(search, 400);

  const loadUsers = useCallback(async () => {
    setLoading(true);
    const result = await getUsers({ search: debouncedSearch, filter });
    if (result.success) {
      setUsers((result.data as any)?.users || []);
    }
    setLoading(false);
  }, [debouncedSearch, filter]);

  useEffect(() => { loadUsers(); }, [loadUsers]);

  async function handleRevoke(userId: string) {
    setActionLoading(userId + '_revoke');
    const result = await revokeLicense({ userId });
    if (result.success) {
      toast.success('تم إلغاء الترخيص بنجاح');
      await loadUsers();
    } else {
      toast.error(result.error || 'فشل إلغاء الترخيص');
    }
    setActionLoading(null);
  }

  async function handleActivate(userId: string) {
    setActionLoading(userId + '_activate');
    const result = await activateLicense({ userId });
    if (result.success) {
      toast.success('تم تفعيل الترخيص بنجاح');
      await loadUsers();
    } else {
      toast.error(result.error || 'فشل تفعيل الترخيص');
    }
    setActionLoading(null);
  }

  async function handleResetDevices(userId: string) {
    if (!confirm('هل أنت متأكد من إعادة تعيين الأجهزة؟')) return;
    setActionLoading(userId + '_devices');
    const result = await resetDevices({ userId });
    if (result.success) {
      toast.success('تم إعادة تعيين الأجهزة');
      await loadUsers();
    } else {
      toast.error(result.error || 'فشل إعادة تعيين الأجهزة');
    }
    setActionLoading(null);
  }

  // تجميع أعضاء المكتب تحت حساب المالك
  const [hiddenGroups, setHiddenGroups] = useState<Set<string>>(new Set());
  const toggleGroup = (id: string) =>
    setHiddenGroups(prev => {
      const n = new Set(prev);
      if (n.has(id)) n.delete(id); else n.add(id);
      return n;
    });

  const membersByOwner = new Map<string, User[]>();
  const topUsers: User[] = [];
  for (const u of users) {
    if (u.office_member_of && !u.is_office_owner && users.some(o => o.id === u.office_member_of!.owner_id)) {
      const k = u.office_member_of.owner_id;
      if (!membersByOwner.has(k)) membersByOwner.set(k, []);
      membersByOwner.get(k)!.push(u);
    } else {
      topUsers.push(u);
    }
  }

  function exportCSV() {
    const headers = ['البريد الإلكتروني', 'نوع الترخيص', 'حالة الترخيص', 'عدد الأجهزة', 'تاريخ التسجيل'];
    const rows = users.map(u => [
      u.email,
      u.license ? LICENSE_LABELS[u.license.license_type] || u.license.license_type : 'لا يوجد',
      u.license?.is_active ? 'نشط' : 'معطل',
      u.device_count,
      new Date(u.created_at).toLocaleDateString('ar-DZ'),
    ]);
    const bom = '\uFEFF';
    const csv = bom + [headers, ...rows].map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'users.csv'; a.click();
    URL.revokeObjectURL(url);
  }

  return (
    <>
      {showCreate && (
        <CreateUserModal onClose={() => setShowCreate(false)} onSuccess={loadUsers} />
      )}

      <div className="space-y-6">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <h1 className="page-title">إدارة المستخدمين</h1>
          <div className="flex items-center gap-2">
            {selected.size > 0 && (
              <button
                onClick={handleBulkDelete}
                disabled={bulkLoading}
                className="btn-danger"
              >
                {bulkLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                حذف المحدد ({selected.size})
              </button>
            )}
            <button onClick={exportCSV} className="btn-secondary">
              <Download className="w-4 h-4" /> تصدير CSV
            </button>
            <button onClick={loadUsers} className="btn-secondary">
              <RefreshCw className="w-4 h-4" />
            </button>
            <button onClick={() => setShowCreate(true)} className="btn-primary">
              <UserPlus className="w-4 h-4" /> إضافة مستخدم
            </button>
          </div>
        </div>

        <div className="card">
          {/* Filters */}
          <div className="flex items-center gap-3 mb-6 flex-wrap">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-dark-500 w-4 h-4" />
              <input
                type="text"
                placeholder="بحث بالبريد أو الاسم أو الهاتف..."
                value={search}
                onChange={e => setSearch(e.target.value)}
                className="input-field pr-10"
                dir="ltr"
              />
            </div>
            <select value={filter} onChange={e => setFilter(e.target.value)} className="select-field w-40">
              <option value="">الكل</option>
              <option value="active">نشط فقط</option>
              <option value="inactive">معطل فقط</option>
              <option value="no_license">بدون ترخيص</option>
            </select>
          </div>

          {/* Table */}
          {loading ? (
            <div className="flex items-center justify-center py-20">
              <Loader2 className="w-8 h-8 animate-spin text-primary-400" />
            </div>
          ) : users.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-dark-500">
              <AlertCircle className="w-12 h-12 mb-3 opacity-40" />
              <p>لا يوجد مستخدمين</p>
            </div>
          ) : (
            <div className="overflow-x-auto -mx-6">
              <table className="w-full">
                <thead>
                  <tr className="border-b border-dark-800">
                    <th className="table-header w-10">
                      <input
                        type="checkbox"
                        checked={users.length > 0 && selected.size === users.length}
                        onChange={toggleSelectAll}
                      />
                    </th>
                    <th className="table-header">المستخدم</th>
                    <th className="table-header">الاسم</th>
                    <th className="table-header">الهاتف</th>
                    <th className="table-header">التسجيل</th>
                    <th className="table-header">الترخيص</th>
                    <th className="table-header">الحالة</th>
                    <th className="table-header">الأجهزة</th>
                    <th className="table-header">آخر دخول</th>
                    <th className="table-header">الإجراءات</th>
                  </tr>
                </thead>
                <tbody>
                  {(() => {
                    const rows: Array<{ u: typeof users[number]; m: boolean }> = [];
                    for (const t of topUsers) {
                      rows.push({ u: t, m: false });
                      if (!hiddenGroups.has(t.id)) {
                        for (const mem of (membersByOwner.get(t.id) || [])) rows.push({ u: mem, m: true });
                      }
                    }
                    return rows.map(({ u: user, m }) => (
                    <tr key={user.id} className={"table-row" + (m ? " bg-dark-800/40" : "")}>
                      <td className="table-cell">
                        <input
                          type="checkbox"
                          checked={selected.has(user.id)}
                          onChange={() => toggleSelect(user.id)}
                        />
                      </td>
                      <td className="table-cell">
                        <div style={m ? { paddingRight: '1.5rem' } : undefined}>
                          {!m && membersByOwner.get(user.id)?.length ? (
                            <button
                              onClick={() => toggleGroup(user.id)}
                              className="inline-flex items-center gap-1 text-xs text-primary-400 hover:text-primary-300 mb-1"
                              title={hiddenGroups.has(user.id) ? 'إظهار أعضاء المكتب' : 'إخفاء أعضاء المكتب'}
                            >
                              <Users2 className="w-3.5 h-3.5" />
                              {membersByOwner.get(user.id)!.length} أعضاء {hiddenGroups.has(user.id) ? '▾' : '▴'}
                            </button>
                          ) : null}
                          {m && user.office_member_of?.owner_email && (
                            <p className="text-[10px] text-dark-500">عضو عند: {user.office_member_of.owner_email}</p>
                          )}
                          <p className="font-medium text-dark-100">{user.email}</p>
                          {!m && <p className="text-xs text-dark-500 mt-0.5 font-mono">{user.id.slice(0, 8)}...</p>}
                        </div>
                      </td>
                      <td className="table-cell text-dark-200 text-sm">{user.full_name || '—'}</td>
                      <td className="table-cell text-dark-300 text-xs" dir="ltr">{user.phone || '—'}</td>
                      <td className="table-cell text-dark-400 text-xs">
                        {user.created_at ? new Date(user.created_at).toLocaleDateString('ar-DZ') : '—'}
                      </td>
                      <td className="table-cell">
                        {user.license ? (
                          <span className={LICENSE_BADGE[user.license.license_type] || 'badge-gray'}>
                            {LICENSE_LABELS[user.license.license_type] || user.license.license_type}
                          </span>
                        ) : (
                          <span className="badge-gray">لا يوجد</span>
                        )}
                      </td>
                      <td className="table-cell">
                        {user.license ? (
                          user.license.is_active
                            ? <span className="badge-green">✓ نشط</span>
                            : <span className="badge-red">✗ معطل</span>
                        ) : (
                          <span className="badge-gray">—</span>
                        )}
                      </td>
                      <td className="table-cell">
                        <span className="badge-purple">
                          <Smartphone className="w-3 h-3" /> {user.device_count}
                        </span>
                      </td>
                      <td className="table-cell text-dark-400 text-xs">
                        {user.last_sign_in_at
                          ? new Date(user.last_sign_in_at).toLocaleDateString('ar-DZ')
                          : '—'}
                      </td>
                      <td className="table-cell">
                        <div className="flex items-center gap-1.5">
                          {user.license && (
                            user.license.is_active ? (
                              <button
                                onClick={() => handleRevoke(user.id)}
                                disabled={actionLoading === user.id + '_revoke'}
                                className="btn-danger py-1 px-2 text-xs"
                                title="إلغاء الترخيص"
                              >
                                {actionLoading === user.id + '_revoke'
                                  ? <Loader2 className="w-3 h-3 animate-spin" />
                                  : <ShieldOff className="w-3 h-3" />}
                              </button>
                            ) : (
                              <button
                                onClick={() => handleActivate(user.id)}
                                disabled={actionLoading === user.id + '_activate'}
                                className="btn-success py-1 px-2 text-xs"
                                title="تفعيل الترخيص"
                              >
                                {actionLoading === user.id + '_activate'
                                  ? <Loader2 className="w-3 h-3 animate-spin" />
                                  : <Shield className="w-3 h-3" />}
                              </button>
                            )
                          )}
                          <button
                            onClick={() => handleDeleteSingle(user.id)}
                            disabled={actionLoading === user.id + '_delete'}
                            className="btn-danger py-1 px-2 text-xs"
                            title="حذف المستخدم نهائياً"
                          >
                            {actionLoading === user.id + '_delete'
                              ? <Loader2 className="w-3 h-3 animate-spin" />
                              : <Trash2 className="w-3 h-3" />}
                          </button>
                          <button
                            onClick={() => handleResetDevices(user.id)}
                            disabled={actionLoading === user.id + '_devices'}
                            className="btn-secondary py-1 px-2 text-xs border-dark-700"
                            title="إعادة تعيين الأجهزة"
                          >
                            {actionLoading === user.id + '_devices'
                              ? <Loader2 className="w-3 h-3 animate-spin" />
                              : <Smartphone className="w-3 h-3" />}
                          </button>
                        </div>
                      </td>
                    </tr>
                    ));
                  })()}
                </tbody>
              </table>
            </div>
          )}

          {/* Count */}
          {!loading && users.length > 0 && (
            <p className="text-xs text-dark-500 mt-4">{users.length} مستخدم</p>
          )}
        </div>
      </div>
    </>
  );
}
