import { Clock } from 'lucide-react';
import { useLocation } from 'react-router-dom';

const pageTitles: Record<string, string> = {
  '/':         'لوحة القيادة',
  '/users':    'إدارة المستخدمين',
  '/licenses': 'إدارة التراخيص',
  '/devices':  'إدارة الأجهزة',
  '/reports':  'التقارير والإحصائيات',
};

export function Header() {
  const location = useLocation();
  const title = pageTitles[location.pathname] || 'لوحة القيادة';

  const now = new Date().toLocaleDateString('ar-DZ', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  return (
    <header className="bg-dark-950 border-b border-dark-800 px-6 py-4 sticky top-0 z-20">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-dark-50">{title}</h2>
          <div className="flex items-center gap-1.5 mt-0.5">
            <Clock className="w-3 h-3 text-dark-500" />
            <p className="text-xs text-dark-500">{now}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 px-3 py-1.5 bg-emerald-500/10 border border-emerald-500/20 rounded-full">
            <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse" />
            <span className="text-xs text-emerald-400 font-medium">متصل</span>
          </div>
        </div>
      </div>
    </header>
  );
}
