import { useEffect, useState, useCallback } from 'react';
import { Filter, RefreshCw, ShieldOff, Shield, Loader2, AlertCircle, Pencil } from 'lucide-react';
import { getLicenses, revokeLicense, activateLicense, updateLicense } from '../services/api';
import { useToast } from '../components/ui/ToastProvider';

interface License {
  id: string;
  user_id: string;
  user_email: string;
  license_type: string;
  is_active: boolean;
  expires_at: string | null;
  activated_at: string;
  created_at: string;
  max_devices: number;
  max_companies: number;
  is_lifetime: boolean;
  payment_id: string | null;
  device_count?: number;
}

const TYPE_LABELS: Record<string, string> = {
  trial: 'تجريبي', standard: 'قياسي', pro: 'احترافي', office: 'مكتبي', office_member: 'عضو مكتب'
};
const TYPE_BADGE: Record<string, string> = {
  trial: 'badge-blue', standard: 'badge-green', pro: 'badge-purple', office: 'badge-orange', office_member: 'badge-gray'
};

function EditLicenseModal({ license, onClose, onSuccess }: { license: License; onClose: () => void; onSuccess: () => void }) {
  const toast = useToast();
  const [licenseType, setLicenseType] = useState(license.license_type);
  const [isLifetime, setIsLifetime] = useState(license.is_lifetime);
  const [expiresAt, setExpiresAt] = useState(
    license.expires_at ? new Date(license.expires_at).toISOString().slice(0, 10) : ''
  );
  const [maxDevices, setMaxDevices] = useState(String(license.max_devices));
  const [paymentId, setPaymentId] = useState(license.payment_id || '');
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setLoading(true);
    const result = await updateLicense({
      userId: license.user_id,
      licenseType,
      isLifetime,
      ...( !isLifetime && expiresAt ? { expiresAt: new Date(expiresAt + 'T23:59:59Z').toISOString() } : {}),
      maxDevices: Number(maxDevices),
      paymentId: paymentId.trim() === '' ? null : paymentId.trim(),
    });
    if (result.success) {
      toast.success('تم تحديث الترخيص بنجاح');
      onSuccess();
      onClose();
    } else {
      toast.error(result.error || 'فشل تحديث الترخيص');
    }
    setLoading(false);
  }

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-dark-900 border border-dark-700 rounded-2xl w-full max-w-md shadow-2xl animate-fade-in">
        <div className="flex items-center justify-between p-6 border-b border-dark-800">
          <h3 className="text-lg font-bold text-dark-50">تعديل ترخيص — {license.user_email}</h3>
          <button onClick={onClose} className="text-dark-400 hover:text-dark-200">✕</button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div>
            <label className="block text-sm text-dark-300 mb-2">النوع</label>
            <select value={licenseType} onChange={e => setLicenseType(e.target.value)} className="select-field">
              <option value="trial">تجريبي</option>
              <option value="standard">قياسي</option>
              <option value="pro">احترافي</option>
              <option value="office">مكتبي</option>
            </select>
            <p className="text-xs text-dark-500 mt-1">تغيير النوع يطبّق حدود النوع الافتراضية (تُستبدل بالقيم التي تدخلها هنا)</p>
          </div>
          <div className="flex items-center gap-2">
            <input type="checkbox" id="lifetime" checked={isLifetime} onChange={e => setIsLifetime(e.target.checked)} />
            <label htmlFor="lifetime" className="text-sm text-dark-200">مدى الحياة (بلا انتهاء)</label>
          </div>
          {!isLifetime && (
            <div>
              <label className="block text-sm text-dark-300 mb-2">تاريخ الانتهاء</label>
              <input type="date" value={expiresAt} onChange={e => setExpiresAt(e.target.value)} required className="input-field" dir="ltr" />
            </div>
          )}
          <div>
            <label className="block text-sm text-dark-300 mb-2">الحد الأقصى للأجهزة</label>
            <input type="number" min={1} max={100} value={maxDevices} onChange={e => setMaxDevices(e.target.value)} required className="input-field" dir="ltr" />
          </div>
          <div>
            <label className="block text-sm text-dark-300 mb-2">معرّف الدفع (اختياري)</label>
            <input type="text" value={paymentId} onChange={e => setPaymentId(e.target.value)} className="input-field" dir="ltr" placeholder="PAY-..." />
          </div>
          <div className="flex gap-3 pt-2">
            <button type="button" onClick={onClose} className="btn-secondary flex-1 justify-center">إلغاء</button>
            <button type="submit" disabled={loading} className="btn-primary flex-1 justify-center">
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Pencil className="w-4 h-4" />}
              حفظ
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export function Licenses() {
  const toast = useToast();
  const [licenses, setLicenses] = useState<License[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterType, setFilterType] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [editing, setEditing] = useState<License | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    const result = await getLicenses({ type: filterType, status: filterStatus });
    if (result.success) {
      setLicenses((result.data as any)?.licenses || []);
    }
    setLoading(false);
  }, [filterType, filterStatus]);

  useEffect(() => { load(); }, [load]);

  async function handleRevoke(userId: string) {
    setActionLoading(userId + '_r');
    const result = await revokeLicense({ userId });
    if (result.success) { toast.success('تم إلغاء الترخيص'); await load(); }
    else toast.error(result.error || 'فشل الإلغاء');
    setActionLoading(null);
  }

  async function handleActivate(userId: string) {
    setActionLoading(userId + '_a');
    const result = await activateLicense({ userId });
    if (result.success) { toast.success('تم تفعيل الترخيص'); await load(); }
    else toast.error(result.error || 'فشل التفعيل');
    setActionLoading(null);
  }

  const total = licenses.length;
  const active = licenses.filter(l => l.is_active).length;

  return (
    <div className="space-y-6">
      {editing && (
        <EditLicenseModal license={editing} onClose={() => setEditing(null)} onSuccess={load} />
      )}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="page-title">إدارة التراخيص</h1>
          <p className="text-dark-400 text-sm mt-1">
            {active} نشط من أصل {total} ترخيص
          </p>
        </div>
        <button onClick={load} className="btn-secondary">
          <RefreshCw className="w-4 h-4" /> تحديث
        </button>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {Object.entries(TYPE_LABELS).map(([type, label]) => {
          const count = licenses.filter(l => l.license_type === type).length;
          return (
            <div key={type} className="card text-center">
              <p className="text-3xl font-bold text-dark-50">{count}</p>
              <span className={`${TYPE_BADGE[type]} mt-2`}>{label}</span>
            </div>
          );
        })}
      </div>

      <div className="card">
        {/* Filters */}
        <div className="flex items-center gap-3 mb-6 flex-wrap">
          <div className="flex items-center gap-2 flex-1 min-w-[180px]">
            <Filter className="w-4 h-4 text-dark-500" />
            <select value={filterType} onChange={e => setFilterType(e.target.value)} className="select-field">
              <option value="">كل الأنواع</option>
              <option value="trial">تجريبي</option>
              <option value="standard">قياسي</option>
              <option value="pro">احترافي</option>
              <option value="office">مكتبي</option>
            </select>
          </div>
          <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="select-field w-40">
            <option value="">كل الحالات</option>
            <option value="active">نشط فقط</option>
            <option value="inactive">معطل فقط</option>
          </select>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-primary-400" />
          </div>
        ) : licenses.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-dark-500">
            <AlertCircle className="w-12 h-12 mb-3 opacity-40" />
            <p>لا توجد تراخيص</p>
          </div>
        ) : (
          <div className="overflow-x-auto -mx-6">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-800">
                  <th className="table-header">المستخدم</th>
                  <th className="table-header">النوع</th>
                  <th className="table-header">الحالة</th>
                  <th className="table-header">الانتهاء</th>
                  <th className="table-header">الأجهزة</th>
                  <th className="table-header">تاريخ الإنشاء</th>
                  <th className="table-header">إجراءات</th>
                </tr>
              </thead>
              <tbody>
                {licenses.map(lic => (
                  <tr key={lic.id} className="table-row">
                    <td className="table-cell">
                      <p className="font-medium text-dark-100">{lic.user_email}</p>
                    </td>
                    <td className="table-cell">
                      <span className={TYPE_BADGE[lic.license_type] || 'badge-gray'}>
                        {TYPE_LABELS[lic.license_type] || lic.license_type}
                      </span>
                    </td>
                    <td className="table-cell">
                      {lic.is_active
                        ? <span className="badge-green">✓ نشط</span>
                        : <span className="badge-red">✗ معطل</span>}
                    </td>
                    <td className="table-cell text-dark-400 text-xs">
                      {lic.is_lifetime ? '∞ مدى الحياة'
                        : lic.expires_at ? new Date(lic.expires_at).toLocaleDateString('ar-DZ')
                        : '—'}
                    </td>
                    <td className="table-cell">
                      <span className="badge-purple">{lic.device_count ?? '—'} / {lic.max_devices} أجهزة</span>
                    </td>
                    <td className="table-cell text-dark-400 text-xs">
                      {new Date(lic.created_at).toLocaleDateString('ar-DZ')}
                    </td>
                    <td className="table-cell">
                      <div className="flex items-center gap-1.5">
                        <button
                          onClick={() => setEditing(lic)}
                          disabled={actionLoading === lic.user_id + '_r' || actionLoading === lic.user_id + '_a'}
                          className="btn-secondary py-1 px-2 text-xs border-dark-700"
                          title="تعديل الترخيص"
                        >
                          <Pencil className="w-3 h-3" />
                        </button>
                        {lic.is_active ? (
                        <button
                          onClick={() => handleRevoke(lic.user_id)}
                          disabled={actionLoading === lic.user_id + '_r'}
                          className="btn-danger py-1 px-2 text-xs"
                        >
                          {actionLoading === lic.user_id + '_r'
                            ? <Loader2 className="w-3 h-3 animate-spin" />
                            : <ShieldOff className="w-3 h-3" />}
                        </button>
                      ) : (
                        <button
                          onClick={() => handleActivate(lic.user_id)}
                          disabled={actionLoading === lic.user_id + '_a'}
                          className="btn-success py-1 px-2 text-xs"
                        >
                          {actionLoading === lic.user_id + '_a'
                            ? <Loader2 className="w-3 h-3 animate-spin" />
                            : <Shield className="w-3 h-3" />}
                        </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
