import React from 'react';
import { NavLink } from 'react-router-dom';
import {
  LayoutDashboard,
  Users,
  Key,
  Smartphone,
  BarChart3,
  LogOut,
  Menu,
  X,
  Shield,
  Inbox,
} from 'lucide-react';
import { useAuth } from '../auth/AuthProvider';

const navItems = [
  { path: '/',        icon: LayoutDashboard, label: 'لوحة القيادة' },
  { path: '/users',   icon: Users,           label: 'المستخدمين'  },
  { path: '/licenses',icon: Key,             label: 'التراخيص'    },
  { path: '/devices', icon: Smartphone,      label: 'الأجهزة'     },
  { path: '/requests',icon: Inbox,           label: 'الطلبات'     },
  { path: '/reports', icon: BarChart3,       label: 'التقارير'    },
];

export function Sidebar() {
  const { admin, signOut } = useAuth();
  const [isOpen, setIsOpen] = React.useState(false);

  return (
    <>
      {/* Mobile toggle */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="lg:hidden fixed top-4 right-4 z-50 p-2 bg-dark-800 border border-dark-700 rounded-lg shadow-lg"
      >
        {isOpen ? <X className="w-5 h-5 text-dark-200" /> : <Menu className="w-5 h-5 text-dark-200" />}
      </button>

      {/* Sidebar */}
      <aside
        className={`fixed top-0 right-0 h-full w-64 bg-dark-900 border-l border-dark-800 
          flex flex-col transform transition-transform duration-300 ease-in-out z-40 
          ${isOpen ? 'translate-x-0' : 'translate-x-full'} lg:translate-x-0`}
      >
        {/* Logo */}
        <div className="px-6 py-5 border-b border-dark-800">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-primary-600 rounded-lg flex items-center justify-center flex-shrink-0">
              <Shield className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-base font-bold text-dark-50">جبايتك</h1>
              <p className="text-xs text-dark-500">لوحة تحكم الأدمن</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
          {navItems.map(({ path, icon: Icon, label }) => (
            <NavLink
              key={path}
              to={path}
              end={path === '/'}
              onClick={() => setIsOpen(false)}
              className={({ isActive }) =>
                `flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 group ${
                  isActive
                    ? 'bg-primary-600/15 text-primary-400 border border-primary-600/20'
                    : 'text-dark-400 hover:text-dark-200 hover:bg-dark-800'
                }`
              }
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span className="font-medium text-sm">{label}</span>
            </NavLink>
          ))}
        </nav>

        {/* User info + logout */}
        <div className="p-4 border-t border-dark-800">
          <div className="flex items-center gap-3 px-2 mb-3">
            <div className="w-8 h-8 rounded-full bg-primary-600/20 border border-primary-600/30 flex items-center justify-center flex-shrink-0">
              <span className="text-xs font-bold text-primary-400">
                {admin?.email?.[0]?.toUpperCase() || 'A'}
              </span>
            </div>
            <div className="min-w-0">
              <p className="text-xs font-medium text-dark-200 truncate">{admin?.email}</p>
              <p className="text-xs text-dark-500">
                {admin?.role === 'super_admin' ? '⭐ أدمن رئيسي' : '🛡️ أدمن'}
              </p>
            </div>
          </div>
          <button
            onClick={signOut}
            className="w-full flex items-center gap-3 px-3 py-2.5 text-dark-400 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-all duration-200 text-sm font-medium"
          >
            <LogOut className="w-4 h-4" />
            تسجيل الخروج
          </button>
        </div>
      </aside>

      {/* Mobile overlay */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/60 z-30 lg:hidden backdrop-blur-sm"
          onClick={() => setIsOpen(false)}
        />
      )}
    </>
  );
}
