import { useState, useEffect, useCallback } from 'react';
import { Search, RefreshCw, Trash2, Loader2, Smartphone, Clock, Flame } from 'lucide-react';
import { getDevices, resetDevices, deleteDevice, unburnTrialDevice } from '../services/api';
import { useToast } from '../components/ui/ToastProvider';

interface Device {
  id: string;
  user_id: string;
  user_email: string;
  hardware_id: string;
  device_name: string | null;
  last_seen: string | null;
  is_active: boolean;
  activated_at: string | null;
  last_device_change: string | null;
  trial_burned?: boolean;
}

function useDebounce<T>(value: T, delay: number): T {
  const [dv, setDv] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDv(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return dv;
}

function isRecent(date: string | null, days: number) {
  if (!date) return false;
  return Date.now() - new Date(date).getTime() < days * 24 * 60 * 60 * 1000;
}

export function Devices() {
  const toast = useToast();
  const [devices, setDevices] = useState<Device[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  const debouncedSearch = useDebounce(search, 400);

  const load = useCallback(async () => {
    setLoading(true);
    const result = await getDevices({ search: debouncedSearch });
    if (result.success) {
      setDevices((result.data as any)?.devices || []);
    }
    setLoading(false);
  }, [debouncedSearch]);

  useEffect(() => { load(); }, [load]);

  async function handleResetUser(userId: string) {
    if (!confirm('هل أنت متأكد من حذف جميع أجهزة هذا المستخدم؟')) return;
    setActionLoading(userId);
    const result = await resetDevices({ userId });
    if (result.success) {
      toast.success((result.data as any)?.message || 'تم إعادة تعيين الأجهزة');
      await load();
    } else {
      toast.error(result.error || 'فشل إعادة التعيين');
    }
    setActionLoading(null);
  }

  async function handleDeleteDevice(deviceId: string) {
    if (!confirm('حذف هذا الجهاز نهائياً؟ سيمكن إعادة تسجيله تلقائياً عند تشغيل التطبيق عليه.')) return;
    setActionLoading('dev_' + deviceId);
    const result = await deleteDevice({ deviceId });
    if (result.success) {
      toast.success('تم حذف الجهاز');
      await load();
    } else {
      toast.error(result.error || 'فشل حذف الجهاز');
    }
    setActionLoading(null);
  }

  async function handleUnburnDevice(hardwareId: string) {
    if (!confirm('تحرير الحرق التجريبي لهذا الجهاز؟ سيصبح مؤهلاً للحصول على فترة تجريبية جديدة.')) return;
    setActionLoading('unburn_' + hardwareId);
    const result = await unburnTrialDevice({ hardwareId });
    if (result.success) {
      toast.success('تم تحرير الحرق التجريبي');
      await load();
    } else {
      toast.error(result.error || 'فشل تحرير الحرق');
    }
    setActionLoading(null);
  }

  const activeCount = devices.filter(d => isRecent(d.last_seen, 7)).length;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="page-title">إدارة الأجهزة</h1>
          <p className="text-dark-400 text-sm mt-1">
            {activeCount} جهاز نشط (آخر 7 أيام) من أصل {devices.length}
          </p>
        </div>
        <button onClick={load} className="btn-secondary">
          <RefreshCw className="w-4 h-4" /> تحديث
        </button>
      </div>

      <div className="card">
        {/* Search */}
        <div className="mb-6">
          <div className="relative w-full max-w-md">
            <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-dark-500 w-4 h-4" />
            <input
              type="text"
              placeholder="بحث باسم الجهاز..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="input-field pr-10"
            />
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-primary-400" />
          </div>
        ) : devices.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-dark-500">
            <Smartphone className="w-12 h-12 mb-3 opacity-40" />
            <p>لا توجد أجهزة مسجلة</p>
          </div>
        ) : (
          <div className="overflow-x-auto -mx-6">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-800">
                  <th className="table-header">المستخدم</th>
                  <th className="table-header">اسم الجهاز</th>
                  <th className="table-header">البصمة</th>
                  <th className="table-header">آخر ظهور</th>
                  <th className="table-header">الحالة</th>
                  <th className="table-header">إجراءات</th>
                </tr>
              </thead>
              <tbody>
                {devices.map(dev => {
                  const isActive = isRecent(dev.last_seen, 7);
                  return (
                    <tr key={dev.id} className="table-row">
                      <td className="table-cell">
                        <p className="font-medium text-dark-100">{dev.user_email}</p>
                        <p className="text-xs text-dark-500 font-mono">{dev.user_id.slice(0, 8)}...</p>
                      </td>
                      <td className="table-cell">
                        <div className="flex items-center gap-2">
                          <Smartphone className="w-4 h-4 text-dark-500" />
                          <span className="text-dark-200">{dev.device_name || 'غير معروف'}</span>
                        </div>
                      </td>
                      <td className="table-cell">
                        <code className="text-xs text-dark-500 font-mono bg-dark-800 px-2 py-0.5 rounded">
                          {dev.hardware_id?.slice(0, 16) || '—'}...
                        </code>
                      </td>
                      <td className="table-cell">
                        <div className="flex items-center gap-1.5 text-xs text-dark-400">
                          <Clock className="w-3 h-3" />
                          {dev.last_seen ? new Date(dev.last_seen).toLocaleDateString('ar-DZ') : '—'}
                        </div>
                      </td>
                      <td className="table-cell">
                        <div className="flex flex-col items-start gap-1.5">
                          {isActive
                            ? <span className="badge-green">● نشط</span>
                            : <span className="badge-gray">○ غير نشط</span>}
                          {dev.trial_burned && (
                            <span className="badge-red"><Flame className="w-3 h-3" /> محروق للتجربة</span>
                          )}
                        </div>
                      </td>
                      <td className="table-cell">
                        <div className="flex items-center gap-1.5">
                          <button
                            onClick={() => handleDeleteDevice(dev.id)}
                            disabled={actionLoading === 'dev_' + dev.id}
                            className="btn-danger py-1 px-2 text-xs"
                            title="حذف هذا الجهاز فقط"
                          >
                            {actionLoading === 'dev_' + dev.id
                              ? <Loader2 className="w-3 h-3 animate-spin" />
                              : <Trash2 className="w-3 h-3" />}
                          </button>
                          <button
                            onClick={() => handleResetUser(dev.user_id)}
                            disabled={actionLoading === dev.user_id}
                            className="btn-secondary py-1 px-2 text-xs border-dark-700"
                            title="حذف جميع أجهزة المستخدم"
                          >
                            {actionLoading === dev.user_id
                              ? <Loader2 className="w-3 h-3 animate-spin" />
                              : <RefreshCw className="w-3 h-3" />}
                          </button>
                          {dev.trial_burned && (
                            <button
                              onClick={() => handleUnburnDevice(dev.hardware_id)}
                              disabled={actionLoading === 'unburn_' + dev.hardware_id}
                              className="btn-secondary py-1 px-2 text-xs border-dark-700 text-orange-400"
                              title="تحرير الحرق التجريبي — يسمح بفترة تجريبية جديدة"
                            >
                              {actionLoading === 'unburn_' + dev.hardware_id
                                ? <Loader2 className="w-3 h-3 animate-spin" />
                                : <Flame className="w-3 h-3" />}
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
