import { useEffect, useState } from 'react';
import {
  Users, Smartphone, TrendingUp, Loader2,
  RefreshCw, AlertCircle, Clock
} from 'lucide-react';
import { getStats } from '../services/api';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';

interface Stats {
  totalUsers: number;
  activeUsers: number;
  totalDevices: number;
  activeLicenses: number;
  pendingResets: number;
  totalRevenue: number;
  licenseByType: { trial: number; standard: number; pro: number; office: number };
  dailyActivity: Array<{ date: string; count: number }>;
}

const PIE_COLORS = {
  trial:    '#60a5fa',
  standard: '#34d399',
  pro:      '#a78bfa',
  office:   '#f59e0b',
};

const PIE_LABELS: Record<string, string> = {
  trial: 'تجريبي', standard: 'قياسي', pro: 'احترافي', office: 'مكتبي',
  office_member: 'عضو مكتب'
};

function StatCard({
  title, value, icon: Icon, color, subtitle
}: {
  title: string; value: string | number; icon: React.ElementType;
  color: string; subtitle?: string;
}) {
  return (
    <div className="card-hover group">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-sm text-dark-400 font-medium mb-1">{title}</p>
          <p className="text-3xl font-bold text-dark-50">{value.toLocaleString('ar-DZ')}</p>
          {subtitle && <p className="text-xs text-dark-500 mt-1">{subtitle}</p>}
        </div>
        <div className={`p-3 rounded-xl ${color}`}>
          <Icon className="w-5 h-5" />
        </div>
      </div>
    </div>
  );
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-dark-800 border border-dark-700 rounded-lg px-3 py-2 shadow-xl">
        <p className="text-xs text-dark-400 mb-1">{label}</p>
        <p className="text-sm font-semibold text-dark-100">{payload[0].value} نشاط</p>
      </div>
    );
  }
  return null;
};

export function Dashboard() {
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => { loadStats(); }, []);

  async function loadStats() {
    setLoading(true);
    setError('');
    const result = await getStats();
    if (result.success && (result.data as any)?.stats) {
      setStats((result.data as any).stats);
    } else {
      setError(result.error || 'فشل تحميل الإحصائيات');
    }
    setLoading(false);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin text-primary-400 mx-auto mb-3" />
          <p className="text-dark-400 text-sm">جاري تحميل الإحصائيات...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center h-64 gap-4">
        <AlertCircle className="w-12 h-12 text-red-400" />
        <p className="text-dark-400">{error}</p>
        <button onClick={loadStats} className="btn-secondary">
          <RefreshCw className="w-4 h-4" />
          إعادة المحاولة
        </button>
      </div>
    );
  }

  const pieData = stats ? Object.entries(stats.licenseByType as Record<string, number>)
    .filter(([, v]) => (v as number) > 0)
    .map(([key, value]) => ({ name: PIE_LABELS[key], value: value as number, color: PIE_COLORS[key as keyof typeof PIE_COLORS] }))
  : [];

  return (
    <div className="space-y-6">
      {/* Header row */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="page-title">مرحباً بك 👋</h1>
          <p className="text-dark-400 text-sm mt-1">إليك نظرة عامة على منصة جبايتك</p>
        </div>
        <button onClick={loadStats} className="btn-secondary">
          <RefreshCw className="w-4 h-4" />
          تحديث
        </button>
      </div>

      {/* Stats grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="إجمالي المستخدمين"
          value={stats?.totalUsers || 0}
          icon={Users}
          color="bg-blue-500/15 text-blue-400"
          subtitle="مستخدم مسجل"
        />
        <StatCard
          title="المستخدمين النشطين"
          value={stats?.activeUsers || 0}
          icon={TrendingUp}
          color="bg-emerald-500/15 text-emerald-400"
          subtitle="لديهم تراخيص فعّالة"
        />
        <StatCard
          title="الأجهزة المسجلة"
          value={stats?.totalDevices || 0}
          icon={Smartphone}
          color="bg-purple-500/15 text-purple-400"
          subtitle="جهاز مرتبط"
        />
        <StatCard
          title="طلبات إعادة التعيين"
          value={stats?.pendingResets || 0}
          icon={Clock}
          color="bg-orange-500/15 text-orange-400"
          subtitle="في انتظار المراجعة"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Activity Line Chart */}
        <div className="card lg:col-span-2">
          <h3 className="section-title">نشاط المستخدمين (آخر 30 يوم)</h3>
          {stats?.dailyActivity && stats.dailyActivity.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <LineChart data={stats.dailyActivity}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                <XAxis
                  dataKey="date"
                  tick={{ fill: '#64748b', fontSize: 11 }}
                  tickLine={false}
                  axisLine={false}
                  tickFormatter={(v) => new Date(v).toLocaleDateString('ar-DZ', { day: '2-digit', month: 'short' })}
                />
                <YAxis tick={{ fill: '#64748b', fontSize: 11 }} tickLine={false} axisLine={false} />
                <Tooltip content={<CustomTooltip />} />
                <Line
                  type="monotone"
                  dataKey="count"
                  stroke="#3b82f6"
                  strokeWidth={2}
                  dot={false}
                  activeDot={{ r: 4, fill: '#3b82f6', strokeWidth: 0 }}
                />
              </LineChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-dark-500 text-sm">
              لا توجد بيانات نشاط بعد
            </div>
          )}
        </div>

        {/* License Pie Chart */}
        <div className="card">
          <h3 className="section-title">توزيع التراخيص</h3>
          {pieData.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="45%"
                  innerRadius={55}
                  outerRadius={80}
                  paddingAngle={3}
                  dataKey="value"
                >
                  {pieData.map((entry, i) => (
                    <Cell key={i} fill={entry.color} />
                  ))}
                </Pie>
                <Legend
                  iconType="circle"
                  iconSize={8}
                  formatter={(value) => <span className="text-xs text-dark-400">{value}</span>}
                />
                <Tooltip
                  contentStyle={{ background: '#1e293b', border: '1px solid #334155', borderRadius: '8px', color: '#e2e8f0' }}
                />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-dark-500 text-sm">
              لا توجد تراخيص بعد
            </div>
          )}
        </div>
      </div>

      {/* License type breakdown */}
      <div className="card">
        <h3 className="section-title">تفاصيل التراخيص</h3>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
          {Object.entries((stats?.licenseByType || {}) as Record<string, number>).map(([type, count]) => (
            <div key={type} className="bg-dark-800 rounded-xl p-4 flex items-center gap-3">
              <div
                className="w-3 h-3 rounded-full flex-shrink-0"
                style={{ backgroundColor: PIE_COLORS[type as keyof typeof PIE_COLORS] }}
              />
              <div>
                <p className="text-xs text-dark-400">{PIE_LABELS[type]}</p>
                <p className="text-xl font-bold text-dark-100">{count}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
