import { useEffect, useState } from 'react';
import { Loader2, RefreshCw, Download, Users, Key, Smartphone, TrendingUp, History } from 'lucide-react';
import { getStats, getLicenses, getAuditLogs } from '../services/api';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';

const PIE_COLORS = ['#60a5fa', '#34d399', '#a78bfa', '#f59e0b'];
const TYPE_LABELS: Record<string, string> = {
  trial: 'تجريبي', standard: 'قياسي', pro: 'احترافي', office: 'مكتبي',
  office_member: 'عضو مكتب'
};

function StatBlock({ title, value, icon: Icon, color, sub }: {
  title: string; value: string | number; icon: React.ElementType; color: string; sub?: string;
}) {
  return (
    <div className="card-hover">
      <div className="flex items-start gap-3">
        <div className={`p-2.5 rounded-xl ${color}`}><Icon className="w-5 h-5" /></div>
        <div>
          <p className="text-sm text-dark-400">{title}</p>
          <p className="text-2xl font-bold text-dark-50 mt-0.5">{value.toLocaleString('ar-DZ')}</p>
          {sub && <p className="text-xs text-dark-500 mt-0.5">{sub}</p>}
        </div>
      </div>
    </div>
  );
}

const ACTION_LABELS: Record<string, string> = {
  create_user: 'إنشاء مستخدم', update_license: 'تعديل ترخيص',
  revoke_license: 'إلغاء ترخيص', activate_license: 'تفعيل ترخيص',
  delete_device: 'حذف جهاز', reset_devices: 'تصفير الأجهزة',
  delete_users: 'حذف مستخدمين', resolve_reset_request: 'حسم طلب إعادة تعيين',
};

interface AuditLog {
  id: string;
  action: string;
  target_type: string | null;
  target_id: string | null;
  details: any;
  created_at: string;
  admin_email?: string;
}

export function Reports() {
  const [stats, setStats] = useState<any>(null);
  const [licenses, setLicenses] = useState<any[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { load(); }, []);

  async function load() {
    setLoading(true);
    const [sr, lr, ar] = await Promise.all([getStats(), getLicenses({ limit: 200 }), getAuditLogs({ limit: 50 })]);
    if (sr.success) setStats((sr.data as any)?.stats);
    if (lr.success) setLicenses((lr.data as any)?.licenses || []);
    if (ar.success) setAuditLogs((ar.data as any)?.logs || []);
    setLoading(false);
  }

  function exportSummary() {
    if (!stats) return;
    const content = [
      '=== تقرير لوحة التحكم - جبايتك ===',
      `التاريخ: ${new Date().toLocaleDateString('ar-DZ')}`,
      '',
      `إجمالي المستخدمين: ${stats.totalUsers}`,
      `المستخدمين النشطين: ${stats.activeUsers}`,
      `الأجهزة المسجلة: ${stats.totalDevices}`,
      `التراخيص النشطة: ${stats.activeLicenses}`,
      '',
      '--- توزيع التراخيص ---',
      ...Object.entries(stats.licenseByType || {}).map(([k, v]) => `${TYPE_LABELS[k] || k}: ${v}`),
    ].join('\n');

    const blob = new Blob(['\uFEFF' + content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'jibayatic-report.txt'; a.click();
    URL.revokeObjectURL(url);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="w-8 h-8 animate-spin text-primary-400" />
      </div>
    );
  }

  const pieData = Object.entries(stats?.licenseByType || {})
    .filter(([, v]) => (v as number) > 0)
    .map(([k, v], i) => ({ name: TYPE_LABELS[k], value: v as number, color: PIE_COLORS[i] }));

  // Payment data by license type
  const revenueByType = Object.entries(stats?.licenseByType || {}).map(([k, v]) => ({
    name: TYPE_LABELS[k] || k,
    value: v as number,
  }));

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <h1 className="page-title">التقارير والإحصائيات</h1>
        <div className="flex items-center gap-2">
          <button onClick={load} className="btn-secondary"><RefreshCw className="w-4 h-4" /></button>
          <button onClick={exportSummary} className="btn-primary">
            <Download className="w-4 h-4" /> تصدير التقرير
          </button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatBlock title="إجمالي المستخدمين" value={stats?.totalUsers || 0} icon={Users}
          color="bg-blue-500/15 text-blue-400" />
        <StatBlock title="المستخدمين النشطين" value={stats?.activeUsers || 0} icon={TrendingUp}
          color="bg-emerald-500/15 text-emerald-400" />
        <StatBlock title="التراخيص النشطة" value={stats?.activeLicenses || 0} icon={Key}
          color="bg-purple-500/15 text-purple-400" />
        <StatBlock title="الأجهزة المسجلة" value={stats?.totalDevices || 0} icon={Smartphone}
          color="bg-orange-500/15 text-orange-400" />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Bar chart */}
        <div className="card">
          <h3 className="section-title">توزيع التراخيص حسب النوع</h3>
          {revenueByType.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={revenueByType} barSize={40}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                <XAxis dataKey="name" tick={{ fill: '#64748b', fontSize: 12 }} tickLine={false} axisLine={false} />
                <YAxis tick={{ fill: '#64748b', fontSize: 12 }} tickLine={false} axisLine={false} />
                <Tooltip
                  contentStyle={{ background: '#1e293b', border: '1px solid #334155', borderRadius: '8px', color: '#e2e8f0' }}
                />
                <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-dark-500 text-sm">
              لا توجد بيانات
            </div>
          )}
        </div>

        {/* Pie chart */}
        <div className="card">
          <h3 className="section-title">نسبة توزيع التراخيص</h3>
          {pieData.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={pieData} cx="50%" cy="45%" innerRadius={55} outerRadius={80} paddingAngle={3} dataKey="value">
                  {pieData.map((entry, i) => <Cell key={i} fill={entry.color} />)}
                </Pie>
                <Legend iconType="circle" iconSize={8}
                  formatter={(v) => <span className="text-xs text-dark-400">{v}</span>} />
                <Tooltip contentStyle={{ background: '#1e293b', border: '1px solid #334155', borderRadius: '8px', color: '#e2e8f0' }} />
              </PieChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-[220px] flex items-center justify-center text-dark-500 text-sm">
              لا توجد تراخيص
            </div>
          )}
        </div>
      </div>

      {/* Audit Log */}
      <div className="card">
        <h3 className="section-title flex items-center gap-2">
          <History className="w-4 h-4" /> سجل عمليات الأدمن (آخر {auditLogs.length || 50})
        </h3>
        {auditLogs.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-10 text-dark-500 text-sm">
            <History className="w-8 h-8 mb-2 opacity-40" />
            لا توجد عمليات مسجلة بعد
          </div>
        ) : (
          <div className="overflow-x-auto -mx-6">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-800">
                  <th className="table-header">الإجراء</th>
                  <th className="table-header">بواسطة</th>
                  <th className="table-header">الهدف</th>
                  <th className="table-header">تفاصيل</th>
                  <th className="table-header">التاريخ</th>
                </tr>
              </thead>
              <tbody>
                {auditLogs.map(log => {
                  const d = log.details || {};
                  return (
                    <tr key={log.id} className="table-row">
                      <td className="table-cell">
                        <span className="badge-blue">{ACTION_LABELS[log.action] || log.action}</span>
                      </td>
                      <td className="table-cell text-dark-300 text-xs">{log.admin_email}</td>
                      <td className="table-cell text-dark-400 text-xs">
                        {log.target_type ? `${log.target_type}` : '—'}
                        {d.user_id ? <span className="font-mono"> · {String(d.user_id).slice(0, 8)}…</span> : null}
                      </td>
                      <td className="table-cell text-dark-400 text-xs max-w-[280px] truncate" dir="ltr">
                        {JSON.stringify(d)}
                      </td>
                      <td className="table-cell text-dark-400 text-xs">
                        {new Date(log.created_at).toLocaleString('ar-DZ')}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Latest Licenses Table */}
      {licenses.length > 0 && (
        <div className="card">
          <h3 className="section-title">آخر التراخيص المُنشأة</h3>
          <div className="overflow-x-auto -mx-6">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-800">
                  <th className="table-header">المستخدم</th>
                  <th className="table-header">النوع</th>
                  <th className="table-header">الحالة</th>
                  <th className="table-header">تاريخ الإنشاء</th>
                </tr>
              </thead>
              <tbody>
                {licenses.slice(0, 10).map(lic => (
                  <tr key={lic.id} className="table-row">
                    <td className="table-cell text-dark-200">{lic.user_email}</td>
                    <td className="table-cell">
                      <span className="badge badge-blue">{TYPE_LABELS[lic.license_type] || lic.license_type}</span>
                    </td>
                    <td className="table-cell">
                      {lic.is_active
                        ? <span className="badge-green">✓ نشط</span>
                        : <span className="badge-red">✗ معطل</span>}
                    </td>
                    <td className="table-cell text-dark-400 text-xs">
                      {new Date(lic.created_at).toLocaleDateString('ar-DZ')}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
