import React, { createContext, useContext, useState, useEffect } from 'react';
import { type AdminUser, signIn as authSignIn, signOut as authSignOut, onAuthStateChange } from '../../services/auth';

interface AuthContextType {
  admin: AdminUser | null;
  loading: boolean;
  signIn: (email: string, password: string) => Promise<{ success: boolean; error?: string }>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [admin, setAdmin] = useState<AdminUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const { data: { subscription } } = onAuthStateChange(async (event: string, session: any) => {
      if (event === 'SIGNED_IN' && session) {
        const token = session.access_token;
        const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;

        try {
          const response = await fetch(`${supabaseUrl}/functions/v1/admin-auth`, {
            method: 'GET',
            headers: {
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json',
            },
          });

          const result = await response.json();

          if (response.ok && result.admin) {
            setAdmin(result.admin);
          } else {
            await authSignOut();
            setAdmin(null);
          }
        } catch (error) {
          console.error('Error verifying admin:', error);
          setAdmin(null);
        }
      } else if (event === 'SIGNED_OUT') {
        setAdmin(null);
      }
      setLoading(false);
    });

    return () => {
      subscription.unsubscribe();
    };
  }, []);

  const signIn = async (email: string, password: string) => {
    const result = await authSignIn(email, password);
    if (result.success && result.admin) {
      setAdmin(result.admin);
    }
    return result;
  };

  const signOut = async () => {
    await authSignOut();
    setAdmin(null);
  };

  return (
    <AuthContext.Provider value={{ admin, loading, signIn, signOut }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}
