import React, { createContext, useContext, useState, useCallback } from 'react';
import { CheckCircle, XCircle, AlertCircle, X } from 'lucide-react';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: string;
  type: ToastType;
  message: string;
}

interface ToastContextType {
  toasts: Toast[];
  toast: {
    success: (message: string) => void;
    error: (message: string) => void;
    info: (message: string) => void;
  };
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((type: ToastType, message: string) => {
    const id = Math.random().toString(36).slice(2);
    setToasts(prev => [...prev, { id, type, message }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  }, []);

  const remove = (id: string) => setToasts(prev => prev.filter(t => t.id !== id));

  const toast = {
    success: (m: string) => addToast('success', m),
    error:   (m: string) => addToast('error', m),
    info:    (m: string) => addToast('info', m),
  };

  const icons = {
    success: <CheckCircle className="w-5 h-5 text-emerald-400 flex-shrink-0" />,
    error:   <XCircle className="w-5 h-5 text-red-400 flex-shrink-0" />,
    info:    <AlertCircle className="w-5 h-5 text-blue-400 flex-shrink-0" />,
  };

  const borders = {
    success: 'border-emerald-500/30',
    error:   'border-red-500/30',
    info:    'border-blue-500/30',
  };

  return (
    <ToastContext.Provider value={{ toasts, toast }}>
      {children}
      {/* Toast Container */}
      <div className="fixed bottom-4 left-4 z-[100] flex flex-col gap-2 min-w-[300px] max-w-[420px]">
        {toasts.map(t => (
          <div
            key={t.id}
            className={`flex items-center gap-3 px-4 py-3 bg-dark-900 border ${borders[t.type]} rounded-xl shadow-2xl animate-fade-in`}
          >
            {icons[t.type]}
            <p className="text-sm text-dark-100 flex-1">{t.message}</p>
            <button
              onClick={() => remove(t.id)}
              className="text-dark-500 hover:text-dark-300 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within ToastProvider');
  return ctx.toast;
}
