import { useState, useEffect, useCallback } from 'react';
import { RefreshCw, Loader2, Inbox, CheckCircle2, XCircle, Clock } from 'lucide-react';
import { getResetRequests, resolveResetRequest } from '../services/api';
import { useToast } from '../components/ui/ToastProvider';

interface ResetRequest {
  id: string;
  user_id: string;
  user_email: string;
  reason: string;
  status: 'pending' | 'approved' | 'rejected';
  admin_notes: string | null;
  created_at: string;
  resolved_at: string | null;
}

export function Requests() {
  const toast = useToast();
  const [requests, setRequests] = useState<ResetRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [viewAll, setViewAll] = useState(false);
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  const [rejecting, setRejecting] = useState<ResetRequest | null>(null);
  const [rejectNote, setRejectNote] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    const result = await getResetRequests({ status: viewAll ? 'all' : 'pending' });
    if (result.success) {
      setRequests((result.data as any)?.requests || []);
    }
    setLoading(false);
  }, [viewAll]);

  useEffect(() => { load(); }, [load]);

  async function handleApprove(req: ResetRequest) {
    if (!confirm(`الموافقة على الطلب ستحذف كل أجهزة ${req.user_email} نهائياً ويسمح له بالدخول من جهازه. متابعة؟`)) return;
    setActionLoading(req.id + '_a');
    const result = await resolveResetRequest({ requestId: req.id, action: 'approve' });
    if (result.success) {
      toast.success(`تمت الموافقة — حُذف ${(result.data as any)?.devicesCleared ?? 0} جهاز`);
      await load();
    } else {
      toast.error(result.error || 'فشل الحسم');
    }
    setActionLoading(null);
  }

  async function handleRejectConfirm() {
    if (!rejecting) return;
    setActionLoading(rejecting.id + '_r');
    const result = await resolveResetRequest({
      requestId: rejecting.id,
      action: 'reject',
      adminNotes: rejectNote,
    });
    if (result.success) {
      toast.success('تم رفض الطلب');
      setRejecting(null);
      setRejectNote('');
      await load();
    } else {
      toast.error(result.error || 'فشل الحسم');
    }
    setActionLoading(null);
  }

  return (
    <div className="space-y-6">
      {rejecting && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-dark-900 border border-dark-700 rounded-2xl w-full max-w-md shadow-2xl">
            <div className="flex items-center justify-between p-6 border-b border-dark-800">
              <h3 className="text-lg font-bold text-dark-50">سبب الرفض — {rejecting.user_email}</h3>
              <button onClick={() => setRejecting(null)} className="text-dark-400 hover:text-dark-200">✕</button>
            </div>
            <div className="p-6 space-y-4">
              <textarea
                value={rejectNote}
                onChange={e => setRejectNote(e.target.value)}
                rows={4}
                required
                className="input-field w-full"
                placeholder="اشرح سبب الرفض (إلزامي، يظهر في السجل)..."
              />
              <div className="flex gap-3">
                <button onClick={() => setRejecting(null)} className="btn-secondary flex-1 justify-center">إلغاء</button>
                <button
                  onClick={handleRejectConfirm}
                  disabled={actionLoading === rejecting.id + '_r' || rejectNote.trim().length < 3}
                  className="btn-danger flex-1 justify-center"
                >
                  {actionLoading === rejecting.id + '_r'
                    ? <Loader2 className="w-4 h-4 animate-spin" />
                    : <XCircle className="w-4 h-4" />}
                  رفض الطلب
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="page-title">طلبات إعادة تعيين الأجهزة</h1>
          <p className="text-dark-400 text-sm mt-1">طلبات المستخدمين العالقين الذين لا يستطيعون الدخول من أجهزتهم</p>
        </div>
        <div className="flex items-center gap-2">
          <label className="flex items-center gap-2 text-sm text-dark-300 cursor-pointer">
            <input type="checkbox" checked={viewAll} onChange={e => setViewAll(e.target.checked)} />
            عرض المحسومة أيضاً
          </label>
          <button onClick={load} className="btn-secondary"><RefreshCw className="w-4 h-4" /> تحديث</button>
        </div>
      </div>

      <div className="card">
        {loading ? (
          <div className="flex items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-primary-400" />
          </div>
        ) : requests.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-dark-500">
            <Inbox className="w-12 h-12 mb-3 opacity-40" />
            <p>{viewAll ? 'لا توجد طلبات' : 'لا طلبات معلقة — كل شيء تحت السيطرة'}</p>
          </div>
        ) : (
          <div className="overflow-x-auto -mx-6">
            <table className="w-full">
              <thead>
                <tr className="border-b border-dark-800">
                  <th className="table-header">المستخدم</th>
                  <th className="table-header">السبب</th>
                  <th className="table-header">الحالة</th>
                  <th className="table-header">التاريخ</th>
                  <th className="table-header">إجراءات</th>
                </tr>
              </thead>
              <tbody>
                {requests.map(req => (
                  <tr key={req.id} className="table-row">
                    <td className="table-cell font-medium text-dark-100">{req.user_email}</td>
                    <td className="table-cell text-dark-300 text-sm max-w-[320px]">{req.reason}</td>
                    <td className="table-cell">
                      {req.status === 'pending' && <span className="badge-orange"><Clock className="w-3 h-3" /> معلق</span>}
                      {req.status === 'approved' && <span className="badge-green"><CheckCircle2 className="w-3 h-3" /> مقبول</span>}
                      {req.status === 'rejected' && (
                        <span className="badge-red" title={req.admin_notes || ''}>
                          <XCircle className="w-3 h-3" /> مرفوض
                        </span>
                      )}
                      {req.status === 'rejected' && req.admin_notes && (
                        <p className="text-xs text-dark-500 mt-1 max-w-[200px] truncate">{req.admin_notes}</p>
                      )}
                    </td>
                    <td className="table-cell text-dark-400 text-xs">
                      {new Date(req.created_at).toLocaleString('ar-DZ')}
                    </td>
                    <td className="table-cell">
                      {req.status === 'pending' ? (
                        <div className="flex items-center gap-1.5">
                          <button
                            onClick={() => handleApprove(req)}
                            disabled={!!actionLoading}
                            className="btn-success py-1 px-2 text-xs"
                            title="موافقة: تفريغ أجهزة المستخدم"
                          >
                            {actionLoading === req.id + '_a'
                              ? <Loader2 className="w-3 h-3 animate-spin" />
                              : <CheckCircle2 className="w-3 h-3" />}
                          </button>
                          <button
                            onClick={() => { setRejecting(req); setRejectNote(''); }}
                            disabled={!!actionLoading}
                            className="btn-danger py-1 px-2 text-xs"
                            title="رفض بملاحظة"
                          >
                            <XCircle className="w-3 h-3" />
                          </button>
                        </div>
                      ) : (
                        <span className="text-xs text-dark-500">—</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
